package com.taller.portal.controller;
import com.taller.portal.dto.AuthDtos.*; import com.taller.portal.service.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService s;private final PasswordRecoveryService recovery;public AuthController(AuthService s,PasswordRecoveryService recovery){this.s=s;this.recovery=recovery;}@PostMapping("/login")public AuthResponse login(@Valid @RequestBody Login v){return s.login(v);}@PostMapping("/register")public AuthResponse register(@Valid @RequestBody Register v){return s.register(v);}@PostMapping("/recover/request")@ResponseStatus(HttpStatus.NO_CONTENT)public void request(@Valid @RequestBody RecoveryRequest v,HttpServletRequest r){recovery.request(v,r.getRemoteAddr());}@PostMapping("/recover/confirm")@ResponseStatus(HttpStatus.NO_CONTENT)public void confirm(@Valid @RequestBody RecoveryConfirm v){recovery.confirm(v);}@ExceptionHandler({IllegalArgumentException.class}) ResponseEntity<Map<String,String>> err(Exception e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}}
